7429      private Type sanitizePossibleStupidIntersectionType(Type receiverType) {
7430          if (receiverType instanceof TraitSelfType) {
7431              receiverType = ((TraitSelfType) receiverType).getNamed();
7432          }
7433          if (receiverType instanceof NamedType)
7434              return receiverType;
