7438              for (Type t : it.getElements()) {
7439                      t = sanitizePossibleStupidIntersectionType(t);
7440                      if (at == null)
7441                          at = t;
7442                      else {
7443                          CFormula c1 = typeAnalyzer.subtype(t, at);
7444                          CFormula c2 = typeAnalyzer.subtype(at, t);
7445                          if (Formula.isTrue(c1, typeAnalyzer)) {
7446                              at = t;
7447                          } else if (Formula.isTrue(c2, typeAnalyzer)) {
7448                              // at is subtype, do nothing.
7449                          } else {
7450                              return receiverType;
7451                          }
7452                         
7453                      }
7454                  
7455              }
7456              return at;
7457          }
7458          return receiverType;
